use crate::aap::caps::http_client;
use crate::aap::caps::notifier;

struct Node;

/// Percent-encode a string for use as a URL query value (RFC 3986 unreserved
/// characters pass through; everything else becomes %XX per UTF-8 byte).
fn percent_encode(input: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(input.len());
    for &b in input.as_bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char);
            }
            _ => {
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0F) as usize] as char);
            }
        }
    }
    out
}

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        // Enrichment lookup for the input's text (the digest overview).
        // The fetched record is deliberately not used and transport failures
        // are discarded, so the node's output does not depend on it. A refusal
        // from the host allowlist still traps at the boundary.
        let enrich_url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&composed.overview)
        );
        let _ = http_client::fetch(&enrich_url);

        let message = format!("Digest {}: {}", composed.date, composed.overview);
        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
```

